insert into contents (title,type,status,visibility,access,section_id,story,created_at) values
('{"en": "1. His Birth ﷺ", "ar": "1. مولده ﷺ"}'::jsonb,'story','published','public','free',(select id from s),'{"hum": false, "slides": [{"p": "the Kaaba in old Makkah at dawn, desert mountains around, soft golden light, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Long ago, in the city of Makkah, stood the Kaʿbah — the House that Prophet Ibrāhīm and his son Ismāʿīl built to worship Allah alone.", "ar": "في مكة، منذ زمن بعيد، كانت الكعبة — البيت الذي بناه إبراهيم وابنه إسماعيل لعبادة الله وحده."}}, {"p": "a huge army with elephants far away in a dusty desert valley, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "One year, a king called Abrahah came with a big army and an elephant to destroy the Kaʿbah.", "ar": "وفي عام من الأعوام جاء ملك اسمه أبرهة بجيش كبير ومعه فيل ليهدم الكعبة."}}, {"p": "a flock of small birds flying over a desert sky carrying tiny stones, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Allah sent flocks of birds carrying small stones, and the army was defeated. People called it “the Year of the Elephant.”", "ar": "فأرسل الله طيرًا أبابيل ترميهم بحجارة صغيرة، فهُزم الجيش، وسمّى الناس هذا العام «عام الفيل»."}}, {"p": "a quiet house in old Makkah under a starry sky, a warm lamp in the window, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "In that same year, our Prophet Muḥammad ﷺ was born. His father ʿAbdullāh had passed away before he was born, and his mother was Āminah.", "ar": "وفي هذا العام نفسه وُلد نبينا محمد ﷺ. وكان أبوه عبد الله قد مات قبل ولادته، وأمه آمنة."}}, {"p": "sunrise over Makkah valley, light spreading over the houses, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "His grandfather ʿAbd al-Muṭṭalib was so happy. He named the baby Muḥammad — “the praised one.”", "ar": "وفرح جدّه عبد المطلب فرحًا شديدًا، وسمّاه «محمدًا» — أي كثير الحمد."}}]}'::jsonb, now() + interval '0 second'),
('{"en": "2. His Early Childhood ﷺ", "ar": "2. طفولته الأولى ﷺ"}'::jsonb,'story','published','public','free',(select id from s),'{"hum": false, "slides": [{"p": "open desert with tents of a Bedouin tribe, sheep grazing, blue sky, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "In those days, families in Makkah sent their babies to the desert, where the air was fresh and the Arabic was pure.", "ar": "كان أهل مكة يرسلون أطفالهم إلى البادية، حيث الهواء النقي واللغة العربية الفصيحة."}}, {"p": "a thin old donkey and a camel walking on a desert road toward tents, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "A kind woman called Ḥalīmah al-Saʿdiyyah took him to nurse him. Her tired camel suddenly had plenty of milk!", "ar": "فأخذته امرأة طيبة اسمها حليمة السعدية لترضعه، فصارت ناقتها الضعيفة تدرّ لبنًا كثيرًا!"}}, {"p": "green grass growing in a desert oasis, healthy sheep, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Wherever he went, blessings came: the grass grew and the sheep became healthy and strong.", "ar": "وأينما ذهب حلّت البركة: نبت العشب، وصارت الغنم سمينة قوية."}}, {"p": "a road between Makkah and Madinah with palm trees at sunset, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "When he was six, his mother Āminah took him to visit Madinah. On the way back, she became ill and passed away at a place called al-Abwāʾ.", "ar": "ولما بلغ ست سنين أخذته أمه آمنة لزيارة المدينة، وفي طريق العودة مرضت وماتت في مكان اسمه «الأبواء»."}}, {"p": "an old wise man''s house in Makkah with a carpet and a lamp, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "His grandfather ʿAbd al-Muṭṭalib cared for him, and when the grandfather died, his uncle Abū Ṭālib looked after him with great love.", "ar": "فكفله جدّه عبد المطلب، ولما مات جدّه كفله عمّه أبو طالب وأحبّه حبًّا شديدًا."}}]}'::jsonb, now() + interval '1 second'),
('{"en": "3. During His Boyhood ﷺ", "ar": "3. في صباه ﷺ"}'::jsonb,'story','published','public','free',(select id from s),'{"hum": false, "slides": [{"p": "sheep grazing on Makkah hills at sunrise, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "As a boy he worked as a shepherd, taking care of sheep. All the prophets were shepherds — it teaches patience and kindness.", "ar": "وفي صباه رعى الغنم، وكل الأنبياء رعوا الغنم؛ فالرعي يعلّم الصبر والرحمة."}}, {"p": "a long trade caravan of camels crossing the desert toward Syria, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "At about twelve, he travelled with his uncle Abū Ṭālib in a trade caravan to al-Shām (Syria).", "ar": "ولما بلغ نحو اثنتي عشرة سنة سافر مع عمه أبي طالب في قافلة تجارة إلى الشام."}}, {"p": "an old stone monastery in the desert, a cloud shading a caravan, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "A wise monk called Baḥīrā noticed signs of prophethood in him and told his uncle to take good care of him.", "ar": "فرأى فيه راهبٌ حكيم اسمه «بَحِيرا» علامات النبوة، ونصح عمّه أن يحافظ عليه."}}, {"p": "a calm Makkah street at noon with an empty market, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "He never lied, never hurt anyone and never bowed to idols. Allah protected him from all bad habits.", "ar": "لم يكذب قط، ولم يؤذِ أحدًا، ولم يسجد لصنم أبدًا؛ فقد حفظه الله من كل خُلق سيئ."}}, {"p": "golden light over Makkah houses, a gentle breeze, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Everyone loved him for his good manners.", "ar": "وكان الجميع يحبونه لحُسن أخلاقه."}}]}'::jsonb, now() + interval '2 second'),
('{"en": "4. In His Early Youth ﷺ", "ar": "4. في صدر شبابه ﷺ"}'::jsonb,'story','published','public','free',(select id from s),'{"hum": false, "slides": [{"p": "a gathering hall in old Makkah with lanterns, men''s sandals at the door, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "As a young man he joined “Ḥilf al-Fuḍūl” — a promise among good people to help anyone who was treated unfairly.", "ar": "وفي شبابه شهد «حلف الفضول» — عهد بين أهل الخير لنصرة كل مظلوم."}}, {"p": "a busy old marketplace with spices and cloth, warm colours, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "He was a trader, and people called him “al-Ṣādiq al-Amīn” — the Truthful, the Trustworthy.", "ar": "وعمل بالتجارة، وكان الناس يسمونه «الصادق الأمين»."}}, {"p": "the Kaaba being rebuilt with stones and wooden scaffolding, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "When Quraysh rebuilt the Kaʿbah, the tribes argued: who would put the Black Stone back in its place?", "ar": "ولما أعادت قريش بناء الكعبة اختلفت القبائل: من يضع الحجر الأسود في مكانه؟"}}, {"p": "a large cloth spread on the ground near the Kaaba, a black stone on it, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "He placed the stone on a cloth and asked every tribe to hold an edge. Together they lifted it, and he set it in place.", "ar": "فوضع الحجر على ثوب، وطلب من كل قبيلة أن تمسك بطرف منه، فرفعوه جميعًا، ووضعه هو بيده في مكانه."}}, {"p": "peaceful Makkah evening with stars, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "His wisdom stopped a fight before it began!", "ar": "وهكذا منعت حكمتُه حربًا قبل أن تبدأ!"}}]}'::jsonb, now() + interval '3 second'),
('{"en": "5. His Marriage ﷺ", "ar": "5. زواجه ﷺ"}'::jsonb,'story','published','public','free',(select id from s),'{"hum": false, "slides": [{"p": "a trade caravan returning to Makkah loaded with goods, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "A noble, wise businesswoman called Khadījah heard of his honesty and asked him to take her trade to al-Shām.", "ar": "سمعت خديجة — وكانت امرأة شريفة عاقلة تعمل بالتجارة — عن أمانته، فطلبت منه أن يخرج بتجارتها إلى الشام."}}, {"p": "piles of goods and coins in a merchant tent, bright lamps, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "He came back with a great profit, and her servant Maysarah told her about his fine character.", "ar": "فعاد بربح كبير، وحدّثها غلامها ميسرة عن أخلاقه الكريمة."}}, {"p": "a beautiful house courtyard with a fountain and roses at dusk, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Khadījah wished to marry him, and he agreed. He was twenty-five years old.", "ar": "فرغبت خديجة في الزواج منه، فوافق، وكان عمره خمسًا وعشرين سنة."}}, {"p": "a warm family home with cushions and a lantern, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Their home was full of love and mercy. Allah blessed them with children, including Fāṭimah.", "ar": "وكان بيتهما مليئًا بالمودة والرحمة، ورزقهما الله الأولاد، ومنهم فاطمة."}}, {"p": "sunrise light entering a window of an old house, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Khadījah was the best wife and the first to believe in him later on.", "ar": "وكانت خديجة خير زوجة، وأول من آمن به بعد ذلك."}}]}'::jsonb, now() + interval '4 second'),
('{"en": "6. The Descending of Revelation ﷺ", "ar": "6. نزول الوحي ﷺ"}'::jsonb,'story','published','public','free',(select id from s),'{"hum": false, "slides": [{"p": "a small cave high on a rocky mountain under a starry night sky, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Before he was forty, he loved to sit alone in the cave of Ḥirāʾ on the Mountain of Light, thinking about Allah.", "ar": "قبل الأربعين كان يحب الخلوة في غار حراء على جبل النور يتفكّر في خلق الله."}}, {"p": "bright heavenly light filling a mountain cave, no people, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "At forty, the angel Jibrīl came to him with the first words of the Quran: «اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ».", "ar": "ولما بلغ الأربعين نزل عليه جبريل بأول آيات القرآن: «اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ»."}}, {"p": "a mountain path down to Makkah at dawn, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "He hurried home to Khadījah, and she comforted him: “Allah will never let you down — you are kind to your relatives and help those in need.”", "ar": "فرجع إلى خديجة، فطمأنته وقالت: «والله لا يخزيك الله أبدًا؛ إنك لتصل الرحم وتعين على نوائب الحق»."}}, {"p": "an old house with many books and scrolls, a lamp, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "She took him to her cousin Waraqah ibn Nawfal, who said: this is the same angel who came to Mūsā.", "ar": "فأخذته إلى ابن عمها ورقة بن نوفل، فقال: هذا الناموس الذي نزل على موسى."}}, {"p": "dawn breaking over the whole valley of Makkah, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "From that day, he ﷺ was the Messenger of Allah to all people.", "ar": "ومن ذلك اليوم صار ﷺ رسولَ الله إلى الناس جميعًا."}}]}'::jsonb, now() + interval '5 second'),
('{"en": "7. The Spread of Islam", "ar": "7. الإسلام ينتشر"}'::jsonb,'story','published','public','free',(select id from s),'{"hum": false, "slides": [{"p": "a lamp being lit in a dark room, light spreading, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "At first, he called his family and close friends quietly. Khadījah, Abū Bakr, ʿAlī and Zayd were among the first Muslims.", "ar": "في البداية دعا أهله وأصحابه سرًّا، فكان من أوائل المسلمين: خديجة، وأبو بكر، وعلي، وزيد."}}, {"p": "a quiet house in Makkah with cushions and lamps, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "They met secretly in the house of al-Arqam to learn the Quran.", "ar": "وكانوا يجتمعون سرًّا في دار الأرقم ليتعلموا القرآن."}}, {"p": "the hill of al-Safa in Makkah at morning, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Then Allah commanded him to call openly. He climbed the hill of al-Ṣafā and invited Quraysh to worship Allah alone.", "ar": "ثم أمره الله بالجهر بالدعوة، فصعد جبل الصفا ودعا قريشًا إلى عبادة الله وحده."}}, {"p": "a hot desert sun over sand and a large rock, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Some leaders of Quraysh hurt the believers. Bilāl was tortured under the hot sun, but he kept saying “Aḥad, Aḥad — One, One!”", "ar": "فآذى بعضُ كبار قريش المؤمنين، وعُذّب بلال تحت الشمس الحارقة وهو يقول: «أحدٌ أحد»."}}, {"p": "a flower growing through a crack in a rock, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Even with all the hardship, more and more people believed.", "ar": "ومع كل هذا الأذى كان المسلمون يزدادون يومًا بعد يوم."}}]}'::jsonb, now() + interval '6 second'),
('{"en": "8. The Firm Faith", "ar": "8. العقيدة الثابتة"}'::jsonb,'story','published','public','free',(select id from s),'{"hum": false, "slides": [{"p": "a sailing ship on the Red Sea heading to Africa at sunrise, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Some Muslims travelled to Abyssinia, where a just king, al-Najāshī, protected them.", "ar": "هاجر بعض المسلمين إلى الحبشة، حيث حماهم ملكٌ عادل هو النجاشي."}}, {"p": "a desert valley between mountains with a few tents, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Quraysh boycotted the Muslims and Banū Hāshim in a valley for three years, until the boycott paper was eaten by termites — except Allah''s name.", "ar": "وحاصرت قريشٌ المسلمين وبني هاشم في الشِّعب ثلاث سنين، حتى أكلت الأرَضة صحيفة المقاطعة إلا اسم الله."}}, {"p": "a sad sunset over Makkah, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "In one year he lost his uncle Abū Ṭālib and his beloved wife Khadījah. It was called “the Year of Sorrow.”", "ar": "وفي عام واحد مات عمه أبو طالب وزوجته خديجة، فسُمّي «عام الحزن»."}}, {"p": "a night sky full of stars over Jerusalem''s domes, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Then Allah honoured him with al-Isrāʾ and al-Miʿrāj — a night journey to al-Masjid al-Aqṣā and up to the heavens — where the five prayers were made obligatory.", "ar": "ثم أكرمه الله برحلة الإسراء والمعراج إلى المسجد الأقصى ثم إلى السماوات، وفيها فُرضت الصلوات الخمس."}}, {"p": "a strong old tree standing in a storm, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "The believers stayed firm, because their faith was in their hearts.", "ar": "وثبت المؤمنون، لأن الإيمان كان في قلوبهم."}}]}'::jsonb, now() + interval '7 second'),
('{"en": "9. A Complaint to Allah ﷺ", "ar": "9. الشكوى إلى الله ﷺ"}'::jsonb,'story','published','public','free',(select id from s),'{"hum": false, "slides": [{"p": "a green mountain town with gardens, al-Taif, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "He walked to the town of al-Ṭāʾif to invite its people to Islam.", "ar": "مشى ﷺ إلى الطائف يدعو أهلها إلى الإسلام."}}, {"p": "stones on a dusty path near a garden wall, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "They refused, and some threw stones at him until his feet bled.", "ar": "فرفضوا، ورماه بعضهم بالحجارة حتى سالت الدماء من قدميه."}}, {"p": "a quiet vineyard with grape vines and shade, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "He sat in a garden and raised his hands in a beautiful duʿāʾ, complaining only to Allah of his weakness.", "ar": "فجلس في بستان ورفع يديه بدعاء جميل يشكو إلى الله وحده ضعفه."}}, {"p": "two great mountains with clouds and light between them, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "The angel of the mountains offered to crush the town, but he said: “I hope Allah will bring from their children people who worship Him.”", "ar": "فجاءه ملك الجبال يعرض أن يُطبق عليهم الجبلين، فقال: «أرجو أن يُخرج الله من أصلابهم من يعبد الله»."}}, {"p": "a sunrise over al-Taif''s green hills, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "What mercy! Years later, the people of al-Ṭāʾif became Muslims.", "ar": "يا لها من رحمة! وبعد سنوات أسلم أهل الطائف."}}]}'::jsonb, now() + interval '8 second'),
('{"en": "10. The Migration (Hijrah) ﷺ", "ar": "10. الهجرة ﷺ"}'::jsonb,'story','published','public','free',(select id from s),'{"hum": false, "slides": [{"p": "palm trees of Yathrib (Madinah) at dawn, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "People from Yathrib (later called Madinah) accepted Islam and invited him to come and live with them.", "ar": "أسلم ناسٌ من أهل يثرب — المدينة — ودعوه أن يهاجر إليهم."}}, {"p": "a dark night over Makkah houses with a crescent moon, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Quraysh plotted to harm him, so Allah allowed him to leave. ʿAlī slept in his bed that night.", "ar": "فدبّرت قريش لإيذائه، فأذن الله له بالهجرة، ونام علي في فراشه تلك الليلة."}}, {"p": "a small cave in a rocky mountain with a spider web and a dove''s nest at the entrance, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "He and Abū Bakr hid in the cave of Thawr. Allah protected them, and he said: «لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا».", "ar": "واختبأ هو وأبو بكر في غار ثور، فحفظهما الله، وقال: «لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا»."}}, {"p": "two camels travelling on a long desert road toward palm trees, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "After three days, they set off on the long road to Madinah.", "ar": "وبعد ثلاثة أيام انطلقا في الطريق الطويل إلى المدينة."}}, {"p": "festive lanterns hanging under palm trees in old Madinah, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "The people of Madinah welcomed him with joy. He built the Prophet''s Mosque and made the Muhājirūn and Anṣār brothers.", "ar": "فاستقبله أهل المدينة بفرح، وبنى المسجد النبوي، وآخى بين المهاجرين والأنصار."}}]}'::jsonb, now() + interval '9 second'),
('{"en": "11. His Expeditions ﷺ", "ar": "11. غزواته ﷺ"}'::jsonb,'story','published','public','free',(select id from s),'{"hum": false, "slides": [{"p": "the wells of Badr in a wide desert at sunrise, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "At Badr, a small group of Muslims met a much bigger army. Allah gave the believers victory.", "ar": "في بدر التقى عدد قليل من المسلمين بجيش كبير، فنصر الله المؤمنين."}}, {"p": "Mount Uhud, red rocks under a cloudy sky, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "At Uḥud, some archers left their places on the hill, and the Muslims learned how important it is to obey the leader.", "ar": "وفي أُحد ترك بعض الرماة أماكنهم على الجبل، فتعلّم المسلمون أهمية طاعة القائد."}}, {"p": "a long trench dug around a city with palm trees, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "In the Battle of the Trench, the Muslims dug a trench around Madinah, as Salmān al-Fārisī suggested.", "ar": "وفي غزوة الخندق حفر المسلمون خندقًا حول المدينة بمشورة سلمان الفارسي."}}, {"p": "a peaceful desert camp under a tree at al-Hudaybiyah, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "At al-Ḥudaybiyah he made a peace treaty, and many people entered Islam during the peace.", "ar": "وفي الحديبية عقد صلحًا، فدخل في الإسلام خلقٌ كثير في وقت السلام."}}, {"p": "Makkah at sunrise with the Kaaba, peaceful and calm, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Then Makkah was opened. He forgave the people who had hurt him: “Go, you are free.”", "ar": "ثم فُتحت مكة، فعفا عمّن آذوه وقال: «اذهبوا فأنتم الطلقاء»."}}]}'::jsonb, now() + interval '10 second'),
('{"en": "12. The Good End ﷺ", "ar": "12. حسن الختام ﷺ"}'::jsonb,'story','published','public','free',(select id from s),'{"hum": false, "slides": [{"p": "the plain of Arafat with Mount Arafat under a bright sky, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "In the tenth year after the Hijrah, he performed the Farewell Ḥajj and gave a great sermon at ʿArafah.", "ar": "في السنة العاشرة للهجرة حجّ حجة الوداع، وخطب الناس خطبة عظيمة في عرفة."}}, {"p": "a scroll and pen beside a lamp, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "He reminded people to be kind, to protect each other''s lives and wealth, and to hold on to the Quran and the Sunnah.", "ar": "وأوصاهم بالرحمة، وحرمة الدماء والأموال، وبالتمسك بكتاب الله وسنته."}}, {"p": "the green dome of the Prophet''s Mosque in Madinah at dusk, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "Soon after, he became ill in Madinah. Even then he kept saying: “The prayer, the prayer!”", "ar": "وبعد ذلك مرض في المدينة، وكان يوصي وهو مريض: «الصلاة، الصلاة»."}}, {"p": "a calm Madinah sky at sunset with soft clouds, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "He ﷺ passed away at sixty-three, having delivered the message completely.", "ar": "وتوفي ﷺ وعمره ثلاث وستون سنة، بعد أن بلّغ الرسالة كاملة."}}, {"p": "sunrise over the whole world, light spreading across lands, children''s book illustration, soft watercolor, no people, no faces, no text", "t": {"en": "We love him, send ṣalawāt upon him, and follow his way every day. ﷺ", "ar": "نحن نحبه، ونصلي عليه، ونتبع سنته كل يوم ﷺ."}}]}'::jsonb, now() + interval '11 second') returning id;